def _banana_local(self, x, y, z):
    """Weltkoordinaten -> unskalierte Bananen-Koordinaten (lx längs, ly Richtung der Wölbung).
    Da sich der Bogen nach hinten wölbt, biegen sich die Enden von selbst zum runden Rücken."""
    s = self.BANANA_SCALE
    qx, qy, qz = (x - self.banana_o[0]) / s, (y - self.banana_o[1]) / s, (z - self.banana_o[2]) / s
    return tuple(qx * e[0] + qy * e[1] + qz * e[2] for e in self.banana_axes)

